							fill="none"
							stroke="currentColor"
							stroke-width="2"
							stroke-linecap="round"
							stroke-linejoin="round"
						>
							<path d="M5 12h14" />
							<path d="m12 5 7 7-7 7" />
						</svg>
						<div class="min-w-0 flex-1 text-right">
							<p class="text-xs text-ui-ink-gray-400">PIC Baru</p>
							<p class="mt-0.5 truncate text-sm font-semibold text-primary">
								{{ detail.data.nama_pic_baru || detail.data.pic_baru || '—' }}
							</p>
						</div>
					</div>
				</div>

				<!-- Rincian -->
				<div class="rounded-2xl border border-ui-line-gray-100 bg-ui-surface p-4 shadow-sm">
