						>
							{{ row.value }}
						</div>
					</div>
				</div>

				<div v-if="detail.data.can_review" class="bottom-bar-spacer" />
			</div>
		</template>

		<!-- ===== Action bar (approver only) ===== -->
		<div
			v-if="detail.data && detail.data.can_review"
			class="fixed inset-x-0 bottom-0 z-30 border-t border-ui-line-gray-100 bg-ui-surface px-4 py-3"
			style="padding-bottom: calc(0.75rem + env(safe-area-inset-bottom))"
		>
			<div class="mx-auto flex max-w-md gap-2">
				<button
					type="button"
					:disabled="!!applying"
					class="flex flex-1 items-center justify-center gap-2 rounded-full border border-ui-line-red-300 bg-ui-surface py-3 text-sm font-semibold text-ui-ink-red-600 shadow-sm transition active:scale-[0.99] disabled:opacity-50"
					@click="openTolak"
				>
					Tolak
				</button>
				<button
					type="button"
					:disabled="!!applying"
					class="flex flex-1 items-center justify-center gap-2 rounded-full bg-primary py-3 text-sm font-semibold text-ui-onPrimary shadow-sm transition active:scale-[0.99] disabled:opacity-50"
					@click="setujui"
				>
					{{ applying === 'Setujui' ? 'Memproses…' : 'Setujui' }}
				</button>
			</div>
		</div>

		<!-- ===== Bottom-sheet alasan Tolak ===== -->
		<Teleport to="body">
			<Transition
				enter-active-class="transition-opacity duration-200"
				enter-from-class="opacity-0"
				leave-active-class="transition-opacity duration-150"
				leave-to-class="opacity-0"
			>
				<div
					v-if="tolakOpen"
					class="fixed inset-0 z-[70] flex items-end justify-center bg-black/40"
					@click.self="tolakOpen = false"
				>
					<Transition
						appear
						enter-active-class="transition-transform duration-200 ease-out"
						enter-from-class="translate-y-full"
						leave-active-class="transition-transform duration-150 ease-in"
						leave-to-class="translate-y-full"
					>
						<div
							v-if="tolakOpen"
							class="w-full max-w-screen-sm rounded-t-3xl bg-ui-surface px-5 pb-[max(1.25rem,env(safe-area-inset-bottom))] pt-3 shadow-2xl"
						>
							<div class="mx-auto mb-4 h-1.5 w-10 rounded-full bg-ui-surface-gray-300" />
							<h2 class="mb-3 text-center text-base font-semibold text-ui-ink-gray-900">
								Alasan Penolakan
							</h2>
							<textarea
								v-model="catatanAdmin"
								rows="3"
								placeholder="Tulis alasan menolak pengajuan Oper PIC ini…"
								class="w-full rounded-xl border border-ui-line-gray-200 px-3 py-2.5 text-sm text-ui-ink-gray-800 focus:border-primary focus:outline-none"
							></textarea>
							<div class="mt-4 flex gap-2">
								<button
									type="button"
									class="flex-1 rounded-full border border-ui-line-gray-200 py-3 text-sm font-semibold text-ui-ink-gray-600 active:scale-[0.99]"
									@click="tolakOpen = false"
								>
									Batal
								</button>
								<button
									type="button"
									:disabled="!catatanAdmin.trim() || !!applying"
									class="flex-1 rounded-full bg-red-600 py-3 text-sm font-semibold text-white active:scale-[0.99] disabled:opacity-50"
									@click="tolak"
								>
									{{ applying === 'Tolak' ? 'Memproses…' : 'Tolak Pengajuan' }}
								</button>
							</div>
						</div>
					</Transition>
				</div>
			</Transition>
		</Teleport>

		<!-- ===== Snackbar ===== -->
		<Teleport to="body">
			<Transition
				enter-active-class="transition-all duration-300 ease-out"
				enter-from-class="opacity-0 translate-y-4"
				leave-active-class="transition-all duration-300 ease-in"
				leave-to-class="opacity-0 translate-y-4"
			>
				<div
					v-if="snack.show"
					class="fixed inset-x-0 z-[100] flex justify-center px-4 pointer-events-none"
					style="bottom: calc(1.25rem + env(safe-area-inset-bottom))"
				>
					<div
						class="pointer-events-auto flex max-w-[400px] items-center gap-2 rounded-md bg-surface-gray-6 px-4 py-2.5 shadow-lg"
					>
						<span class="text-p-sm text-ink-white break-words">{{
							snack.message
						}}</span>
