</template>

<script setup>
import { ref, reactive, computed, watch } from 'vue'
import { createResource } from 'frappe-ui'
import { useBackNavigation } from '../composables/useBackNavigation'

const props = defineProps({
	name: { type: String, required: true },
})
const { goBack } = useBackNavigation({ name: 'WorkflowRequests' }, 'Approval Requests')

// ===== Detail =====
const detail = createResource({
	url: 'juragan.api.portal.oper_pic.get_oper_pic_detail',
	method: 'GET',
	auto: false,
	makeParams: () => ({ name: props.name }),
})
const errorMessage = computed(() => {
	if (!detail.error) return ''
	const e = detail.error
	return e?.messages?.[0] || e?.message || 'Gagal memuat detail pengajuan.'
})

watch(
	() => props.name,
	() => detail.fetch(),
	{ immediate: true }
)

// ===== Rincian yang ditampilkan =====
const infoRows = computed(() => {
	const d = detail.data || {}
	const rows = [
		{ label: 'Cabang', value: d.cabang_collection || '—' },
		{ label: 'Jenis Proses', value: d.jenis_proses || '—' },
		{ label: 'Alasan Oper', value: d.alasan_oper || '—' },
		{ label: 'Diajukan oleh', value: d.diajukan_oleh_nama || d.diajukan_oleh || '—' },
		{ label: 'Waktu Pengajuan', value: formatDateTime(d.waktu_pengajuan) },
	]
	if (d.status && d.status !== 'Menunggu Persetujuan Admin') {
		rows.push({
			label: 'Diproses oleh',
			value: d.diproses_oleh_nama || d.diproses_oleh || '—',
		})
		rows.push({ label: 'Waktu Diproses', value: formatDateTime(d.waktu_diproses) })
		if (d.catatan_admin) rows.push({ label: 'Catatan Admin', value: d.catatan_admin })
	}
	return rows
})

// ===== Approval =====
// Endpoint approval memakai dokumen INDUK (TTS/BSTK), bukan record Oper PIC —
// itu yang menegakkan role Workflow, scope cabang, & allow_self_approval.
const reviewRes = createResource({
	url: 'juragan.collection.oper_pic.review_oper_pic',
	method: 'POST',
})
const applying = ref('')
const tolakOpen = ref(false)
const catatanAdmin = ref('')

function openTolak() {
	catatanAdmin.value = ''
	tolakOpen.value = true
}

async function kirim(action, extra = {}) {
	if (applying.value) return
	applying.value = action
	try {
		const res = await reviewRes.submit({
			doctype: detail.data.jenis_dokumen,
			name: detail.data.dokumen,
			action,
			request_name: props.name,
			...extra,
		})
		tolakOpen.value = false
		await detail.fetch()
		autoToast(res?.message || 'Berhasil diproses.')
		// Kembali ke daftar setelah jeda singkat — pengajuan sudah bukan antrean.
		setTimeout(() => goBack(), 900)
	} catch (e) {
		autoToast(e?.messages?.[0] || e?.message || `Gagal memproses "${action}".`)
	} finally {
		applying.value = ''
	}
}
function setujui() {
	kirim('Setujui')
}
function tolak() {
	const alasan = catatanAdmin.value.trim()
	if (!alasan) return
	kirim('Tolak', { catatan_admin: alasan })
}

// ===== Helpers =====
const STATUS_PILL = {
	'Menunggu Persetujuan Admin': 'bg-ui-surface-amber-100 text-ui-ink-amber-700',
	Disetujui: 'bg-ui-surface-green-100 text-ui-ink-green-700',
	Ditolak: 'bg-ui-surface-red-100 text-ui-ink-red-700',
}
function statusPill(status) {
	return STATUS_PILL[status] || 'bg-ui-surface-gray-100 text-ui-ink-gray-600'
}

const ID_MONTHS = [
	'Jan',
	'Feb',
	'Mar',
	'Apr',
	'Mei',
	'Jun',
	'Jul',
	'Agu',
	'Sep',
	'Okt',
	'Nov',
	'Des',
]
function formatDateTime(v) {
	if (!v) return '—'
	const [datePart, timePart] = String(v).split(' ')
	const [y, m, day] = datePart.split('-')
	if (!y || !m || !day) return String(v)
	let out = `${day} ${ID_MONTHS[Number(m) - 1] || m} ${y}`
	if (timePart) {
		const [hh, mm] = timePart.split('.')[0].split(':')
		if (hh != null) out += ` ${hh}:${mm ?? '00'}`
	}
	return out
}

const snack = reactive({ show: false, message: '' })
let snackTimer = null
function autoToast(message) {
	if (snackTimer) clearTimeout(snackTimer)
	snack.message = message
	snack.show = true
	snackTimer = setTimeout(() => (snack.show = false), 3000)
}

</script>
